    /** 按省/市/区县名取经度：优先区县，其次市，最后省；名称做包含匹配兜底 */
    fun lonOf(province: String, city: String, district: String): Double? {
        val p = PROVINCES.firstOrNull { it.name == province } ?: PROVINCES.firstOrNull { it.name.contains(province) } ?: return null
        val c = p.cities.firstOrNull { it.name == city } ?: p.cities.firstOrNull { it.name.contains(city) } ?: return p.lon
        if (district.isBlank()) return c.lon
        val g = c.districts.firstOrNull { it.name == district } ?: c.districts.firstOrNull { it.name.contains(district) } ?: return c.lon
        return g.lon
    }
